        scrollTo(locator: CodeceptJS.LocatorOrString, offsetX?: number, offsetY?: number): CodeceptJS.ElementStepPromise;
        /**
         * Checks that title contains text.
         *
         * ```js
         * I.seeInTitle('Home Page');
         * ```
         * @param text - text value to check.
         * @returns automatically synchronized promise through #recorder
         */
        seeInTitle(text: string): CodeceptJS.StepPromise;
        /**
         * Retrieves a page scroll position and returns it to test.
         * Resumes test execution, so **should be used inside an async function with `await`** operator.
         *
         * ```js
         * let { x, y } = await I.grabPageScrollPosition();
         * ```
         * @returns scroll position
         */
        grabPageScrollPosition(): Promise<PageScrollPosition>;
        /**
         * Checks that title is equal to provided one.
         *
         * ```js
         * I.seeTitleEquals('Test title.');
         * ```
         * @param text - value to check.
         * @returns automatically synchronized promise through #recorder
         */
        seeTitleEquals(text: string): CodeceptJS.StepPromise;
